// === Tab: mySketch ===
/*
Assignment:
Create a Particle System using custom Javascript Objects (ES6 class notation).
Your Particle object must contain the following properties: 
position, size, color, speed.
*/

class Particle {
	//Particle constructor takes two inputs: pos (position) and size
	//pos should be a p5 vector and size should be an int
	constructor(pos, size) {

		//establish object properties including position, size, color and speed
		this.pos = pos;
		this.size = size;
		//white in HSB
		this.color = color(360, 0, 100);
		// object speed is proportional to size, equation makes it slow enough to see)
		this.Xspeed = random(-size / 25, size / 25);
		this.Yspeed = random(-size / 25, size / 25);
		this.lifespan = 500;
	}
	bounce() {
		// function to bounce around the canvas
		if (this.pos.y >= height || this.pos.y <= 0) {
			this.Yspeed *= -1;
			//when it hits top or bottom color it changes
			this.changeColor();
		}
		if (this.pos.x >= width || this.pos.x <= 0) {
			this.Xspeed *= -1;
			//when it hits left or right sides color changes
			this.changeColor();
		}
		this.pos.add(new p5.Vector(this.Xspeed, this.Yspeed));
		// every frame of bouncing reduces lifespan proportional to avg speed
		this.lifespan = this.lifespan - abs((this.Xspeed + this.Yspeed + 1) / 2);
	}

	changeColor() {
		//easily change colors in the bounce function
		let newColor = color(random(360), 100, 100);
		this.color = newColor;
	}
}
//********* End Class definition

function preload() {
	//loads image first before anything else
	logo = loadImage('https://openprocessing.org/sketch/891932/files/dvd_logo_white.png');
}

//establish Global Variables
let bouncing = true; //objects move at the start
let swarm = []; // this is the collection of objects or "particles"
let spawnCount = 2; // how many are created on each click
let swarmMax = 4; // the max allowed onscreen
let imageRatio = 1.84; // the width/height ratio for easily swapping out other images proportionally

function setup() {
	//basic setup of sketch settings behavior
	createCanvas(640, 360);
	colorMode(HSB, 360, 100, 100);
	imageMode(CENTER);
}


function draw() {
	background(20);

	//draw particles in swarm collection
	for (let i = 0; i < swarm.length; i++) {
		if (bouncing) {
			swarm[i].bounce();
		}
		if (swarm.length > 0) {
			//isolates the tint from other objects
			push();
				// colors the white logo by using p5.js tint function
				tint(swarm[i].color);
				//draws the PNG logo at the particle object's location using it's size and pos properties
				image(logo, swarm[i].pos.x, swarm[i].pos.y, swarm[i].size * imageRatio, swarm[i].size);
			pop();
		}
		if (swarm[i].lifespan <= 0) {
			//removes object from collection if its lifespan has depleted
			swarm.splice(i, i + 1);
		}
	}
}

function mousePressed() {
	//left click to spawn more
	if (mouseButton === LEFT) {
		//limits swarm size by only creating more if there's room
		if (swarm.length < swarmMax) {
			for (let i = 0; i < spawnCount; i++) {
				// this is where new objects are instantiated (created)
				// they take a p5 vector for position and random number for their size
				let particle = new Particle(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), random(10, 100));

				//they're then added to the collection (array) of objects to create a particle system
				append(swarm, particle);
			}
		}
	} else if (mouseButton === CENTER) {
		//pauses all movement, click again to resume
		bouncing = !bouncing;
	}
}

